-- The Quiet Ledger: seed data
-- Deterministic, self-contained PostgreSQL seed data. 10 tables, 250 rows each.
-- This file is complete and is the only script you need. Two deliberate twists are built into the seed rows:
--   * transfer 214 is stamped 2026-08-14 02:14:00 (collides on purpose with transfer 194)
--   * call 191 uses device 1020, which was retired on 2026-06-30 (contradicts the device register)
-- people.photo (BYTEA) holds a 178x218 JPEG for every person: person_id N carries image N (000001.jpg .. 000250.jpg)
-- as inline hexadecimal bytea data.

DROP TABLE IF EXISTS person_location;
DROP TABLE IF EXISTS calls;
DROP TABLE IF EXISTS access_logs;
DROP TABLE IF EXISTS evidence_transfers;
DROP TABLE IF EXISTS evidence;
DROP TABLE IF EXISTS case_people;
DROP TABLE IF EXISTS cases;
DROP TABLE IF EXISTS devices;
DROP TABLE IF EXISTS locations;
DROP TABLE IF EXISTS people;

CREATE TABLE people (
  person_id INTEGER PRIMARY KEY,
  full_name TEXT NOT NULL,
  role TEXT NOT NULL,
  division TEXT NOT NULL,
  clearance_level INTEGER NOT NULL,
  joined_on DATE NOT NULL,
  active BOOLEAN NOT NULL,
  badge_code TEXT NOT NULL UNIQUE,
  shift_code TEXT NOT NULL,
  employment_type TEXT NOT NULL,
  clearance_expiry DATE NOT NULL,
  photo BYTEA NOT NULL
);

CREATE TABLE locations (
  location_id INTEGER PRIMARY KEY,
  location_name TEXT NOT NULL,
  zone TEXT NOT NULL,
  restricted BOOLEAN NOT NULL,
  floor INTEGER NOT NULL,
  camera_id TEXT NOT NULL UNIQUE,
  building TEXT NOT NULL,
  room_code TEXT NOT NULL UNIQUE,
  badge_level_required INTEGER NOT NULL,
  map_code TEXT NOT NULL
);

CREATE TABLE devices (
  device_id INTEGER PRIMARY KEY,
  owner_id INTEGER NOT NULL REFERENCES people(person_id),
  device_type TEXT NOT NULL,
  phone_number TEXT NOT NULL UNIQUE,
  issued_on DATE NOT NULL,
  retired_on DATE,
  imei_hash TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  encryption_key_id TEXT NOT NULL
);

CREATE TABLE cases (
  case_id INTEGER PRIMARY KEY,
  case_ref TEXT NOT NULL UNIQUE,
  opened_on DATE NOT NULL,
  case_type TEXT NOT NULL,
  priority TEXT NOT NULL,
  lead_person_id INTEGER NOT NULL REFERENCES people(person_id),
  status TEXT NOT NULL,
  closed_on DATE,
  origin_location_id INTEGER NOT NULL REFERENCES locations(location_id),
  incident_code TEXT NOT NULL UNIQUE,
  classification TEXT NOT NULL
);

CREATE TABLE case_people (
  record_id INTEGER PRIMARY KEY,
  case_id INTEGER NOT NULL REFERENCES cases(case_id),
  person_id INTEGER NOT NULL REFERENCES people(person_id),
  relation TEXT NOT NULL,
  assigned_on DATE NOT NULL,
  end_on DATE,
  clearance_snapshot INTEGER NOT NULL
);

CREATE TABLE evidence (
  evidence_id INTEGER PRIMARY KEY,
  case_id INTEGER NOT NULL REFERENCES cases(case_id),
  evidence_type TEXT NOT NULL,
  item_code TEXT NOT NULL UNIQUE,
  collected_at DATE NOT NULL,
  collected_by INTEGER NOT NULL REFERENCES people(person_id),
  current_location_id INTEGER REFERENCES locations(location_id),
  sealed BOOLEAN NOT NULL,
  status TEXT NOT NULL,
  risk_class TEXT NOT NULL,
  weight_grams NUMERIC(7,1) NOT NULL,
  hash_fragment TEXT NOT NULL
);

CREATE TABLE evidence_transfers (
  transfer_id INTEGER PRIMARY KEY,
  evidence_id INTEGER NOT NULL REFERENCES evidence(evidence_id),
  actor_id INTEGER NOT NULL REFERENCES people(person_id),
  from_location_id INTEGER NOT NULL REFERENCES locations(location_id),
  to_location_id INTEGER NOT NULL REFERENCES locations(location_id),
  transfer_time TIMESTAMP NOT NULL,
  method TEXT NOT NULL,
  authorization_code TEXT NOT NULL UNIQUE,
  witness_id INTEGER NOT NULL REFERENCES people(person_id),
  seal_state TEXT NOT NULL,
  note_code TEXT NOT NULL
);

CREATE TABLE access_logs (
  access_id INTEGER PRIMARY KEY,
  person_id INTEGER NOT NULL REFERENCES people(person_id),
  location_id INTEGER NOT NULL REFERENCES locations(location_id),
  access_time TIMESTAMP NOT NULL,
  action TEXT NOT NULL,
  result TEXT NOT NULL,
  terminal_id TEXT NOT NULL,
  badge_mode TEXT NOT NULL,
  reason_code TEXT NOT NULL,
  door_cycle INTEGER NOT NULL,
  escort_id INTEGER REFERENCES people(person_id),
  anomaly_flag TEXT NOT NULL
);

CREATE TABLE calls (
  call_id INTEGER PRIMARY KEY,
  caller_id INTEGER NOT NULL REFERENCES people(person_id),
  receiver_id INTEGER NOT NULL REFERENCES people(person_id),
  device_id INTEGER NOT NULL REFERENCES devices(device_id),
  call_time TIMESTAMP NOT NULL,
  duration_sec INTEGER NOT NULL,
  tower_id TEXT NOT NULL,
  call_type TEXT NOT NULL,
  answered BOOLEAN NOT NULL,
  direction TEXT NOT NULL,
  reference_code TEXT NOT NULL UNIQUE
);

CREATE TABLE person_location (
  event_id INTEGER PRIMARY KEY,
  person_id INTEGER NOT NULL REFERENCES people(person_id),
  location_id INTEGER NOT NULL REFERENCES locations(location_id),
  observed_at TIMESTAMP NOT NULL,
  source TEXT NOT NULL,
  confidence NUMERIC(4,2) NOT NULL,
  sensor_id TEXT NOT NULL,
  movement TEXT NOT NULL,
  observation_code TEXT NOT NULL UNIQUE,
  batch_id TEXT NOT NULL
);










